import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { spawnSync } from 'node:child_process'

// Local, dependency-free report. The JSON records remain the source of truth.
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const docs = path.join(root, 'docs')
const readJson = (name, fallback) => {
  const filename = path.join(docs, name)
  return fs.existsSync(filename) ? JSON.parse(fs.readFileSync(filename, 'utf8').replace(/^\uFEFF/, '')) : fallback
}
const matrix = readJson('requisitos.json', { requisitos: [], baseline: [] })
const results = readJson('resultados.json', {})
const reqs = Array.isArray(matrix.requisitos) ? matrix.requisitos : []
const h = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char])
const plain = value => value == null || value === '' ? 'Não informado' : typeof value === 'object' ? JSON.stringify(value, null, 2) : String(value)
const git = args => {
  const result = spawnSync('git', args, { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] })
  return result.status === 0 ? result.stdout.trim() : ''
}
const labels = { APROVADO: '✓ Aprovado', REPROVADO: '✕ Reprovado', PENDENTE: '◷ Pendente', BLOQUEADO: '⚠ Bloqueado', NAO_APLICAVEL: '— Não aplicável' }
const status = row => Object.hasOwn(labels, row.status) ? row.status : 'PENDENTE'
const badge = value => '<span class="badge ' + h(value) + '">' + h(labels[value] || value) + '</span>'
const count = scope => {
  const rows = reqs.filter(row => row.escopo === scope)
  const applicable = rows.filter(row => status(row) !== 'NAO_APLICAVEL')
  const passed = rows.filter(row => status(row) === 'APROVADO').length
  return { total: rows.length, applicable: applicable.length, passed, counts: Object.fromEntries(Object.keys(labels).map(key => [key, rows.filter(row => status(row) === key).length])), percent: applicable.length ? Math.round(passed / applicable.length * 100) : 0 }
}
const academic = count('ACADEMICO')
const extra = count('COMPLEMENTAR')
const verdict = results.veredito || 'EM VALIDAÇÃO — sem veredito final registrado'
const evaluatedCommit = results.commit || 'Ainda não informado'
const branch = results.branch || git(['branch', '--show-current']) || 'Não identificada'
const commitNow = git(['rev-parse', '--short', 'HEAD']) || 'Não identificado'
let repo = ''
const remote = git(['remote', 'get-url', 'origin']).replace(/^git@github\.com:/, 'https://github.com/').replace(/\.git$/, '')
try {
  const parsed = new URL(results.repositorio || remote)
  if (parsed.protocol === 'https:' || parsed.protocol === 'http:') { parsed.username = ''; parsed.password = ''; repo = parsed.href }
} catch { /* An unavailable remote is reported rather than invented. */ }
const link = (relative, label) => fs.existsSync(path.resolve(docs, relative))
  ? '<a href="' + h(relative) + '">' + h(label) + ' <span aria-hidden="true">↗</span></a>'
  : '<span class="muted">' + h(label) + ' · ainda não disponível</span>'
const formatObject = value => value == null ? '<p class="muted">Não coletado neste relatório.</p>' : '<pre class="data-block">' + h(plain(value)) + '</pre>'
const section = (id, eyebrow, title, body) => '<section id="' + id + '" class="section"><div class="section-heading"><p class="eyebrow">' + eyebrow + '</p><h2>' + title + '</h2></div>' + body + '</section>'
const command = (title, code, help = '') => '<div class="command"><div class="command-top"><strong>' + h(title) + '</strong><button type="button" class="copy" aria-label="Copiar comando: ' + h(title) + '">Copiar</button></div><pre><code>' + h(code) + '</code></pre>' + (help ? '<p>' + h(help) + '</p>' : '') + '</div>'
const card = (title, body, cls = '') => '<article class="card ' + cls + '"><h3>' + title + '</h3>' + body + '</article>'
const metric = (title, value) => {
  const valid = value && Number.isFinite(value.passed) && Number.isFinite(value.total) && value.total >= 0 && value.passed >= 0 && value.passed <= value.total
  const amount = valid ? value.passed + '<span> / ' + value.total + '</span>' : '—'
  const percent = valid && value.total > 0 ? value.passed / value.total * 100 : 0
  return '<article class="metric"><p>' + title + '</p><strong>' + amount + '</strong><span class="muted">' + (valid ? 'Aprovados / total informado' : 'Não coletado') + '</span><div class="bar" aria-hidden="true"><i style="width:' + percent + '%"></i></div>' + (value ? '<details><summary>Detalhes registrados</summary>' + formatObject(value) + '</details>' : '') + '</article>'
}
const stats = (title, data) => '<article class="score"><p>' + title + '</p><strong>' + data.percent + '<span>%</span></strong><div class="bar" aria-hidden="true"><i style="width:' + data.percent + '%"></i></div><p>' + data.passed + ' de ' + data.applicable + ' requisitos aplicáveis aprovados</p><small>' + data.total + ' itens mapeados. Evidência, não estimativa de esforço.</small><div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:16px">' + Object.entries(data.counts).map(([key, amount]) => '<span class="badge ' + key + '">' + h(labels[key]) + ': ' + amount + '</span>').join('') + '</div></article>'
const fields = [['origem', 'Pedido original / referência'], ['criterio', 'Critério de aceite'], ['implementacao', 'Solução registrada'], ['teste', 'Como comprovar'], ['evidencia', 'Evidência obtida'], ['commit', 'Commit validado']]
const requirementRows = reqs.map(row => '<details class="requirement" data-status="' + status(row) + '" data-scope="' + h(row.escopo) + '" data-search="' + h([row.id, row.categoria, row.descricao, row.origem, plain(row.implementacao)].join(' ').toLocaleLowerCase('pt-BR')) + '"><summary><span class="req-id">' + h(row.id) + '</span><span class="req-name">' + h(row.descricao) + '<small>' + h(row.categoria) + ' · ' + (row.escopo === 'COMPLEMENTAR' ? 'Pedido complementar' : 'Enunciado acadêmico') + '</small></span>' + badge(status(row)) + '</summary><div class="req-body"><dl>' + fields.map(([key, label]) => '<div><dt>' + label + '</dt><dd>' + h(plain(row[key])) + '</dd></div>').join('') + '</dl></div></details>').join('')
const timeline = git(['log', '-12', '--reverse', '--format=%h%x09%cI%x09%s']).split('\n').filter(Boolean).map(line => {
  const [hash, date, ...subject] = line.split('\t')
  return '<li><span class="timeline-dot" aria-hidden="true"></span><time>' + h(date) + '</time><h3>' + h(subject.join('\t')) + '</h3><code>' + h(hash) + '</code></li>'
}).join('')
const screenshots = [
  ['chamado-a.png', 'Triagem na cópia A', 'Estado do chamado capturado na primeira cópia. A imagem demonstra somente o que está visível nesta captura.'],
  ['chamado-b.png', 'Triagem na cópia B', 'Estado do chamado capturado na segunda cópia. A aprovação do isolamento depende também das provas de banco, worker e anexos.'],
  ['anexo-a.png', 'Anexo na cópia A', 'Captura da jornada de anexos. A prova do arquivo no host precisa constar nos registros de teste.'],
  ['isolamento-b.png', 'Consulta na cópia B', 'Captura utilizada na verificação de isolamento entre as duas interfaces.'],
  ['erro-isolamento.png', 'Tratamento de acesso inválido', 'Evidência visual do resultado de uma tentativa registrada na validação do isolamento.']
]
const gallery = screenshots.map(([filename, title, caption]) => {
  const filepath = path.join(docs, 'evidence', filename)
  if (!fs.existsSync(filepath)) return '<article class="shot pending-shot"><div class="shot-placeholder" aria-hidden="true">▧</div><h3>' + title + '</h3><p>Captura ainda não disponível.</p><small>evidence/' + filename + '</small></article>'
  const data = 'data:image/png;base64,' + fs.readFileSync(filepath).toString('base64')
  return '<figure class="shot"><button type="button" class="zoom" aria-label="Ampliar: ' + title + '"><img src="' + data + '" alt="' + title + ': screenshot real da aplicação" loading="lazy"></button><figcaption><h3>' + title + '</h3><p>' + caption + '</p><small>Fonte: docs/evidence/' + filename + '</small></figcaption></figure>'
}).join('')
const logs = Array.isArray(results.logs) ? results.logs : []
const logList = logs.length ? '<ul class="link-list">' + logs.map(item => {
  const source = typeof item === 'string' ? item : item.path || item.arquivo || item.url || item.caminho || ''
  const label = typeof item === 'string' ? item : item.label || item.nome || source || plain(item)
  if (!source) return '<li>' + h(label) + '</li>'
  if (/^https?:\/\//.test(source)) return '<li><a href="' + h(source) + '" rel="noopener">' + h(label) + '</a></li>'
  const relative = source.replaceAll('\\', '/').replace(/^docs\//, '')
  return '<li>' + link(relative, label) + '</li>'
}).join('') + '</ul>' : '<p class="muted">Nenhum arquivo de log foi vinculado em resultados.json até esta geração.</p>'
const limitations = Array.isArray(results.limitacoes) && results.limitacoes.length
  ? '<ul>' + results.limitacoes.map(item => '<li>' + h(plain(item)) + '</li>').join('') + '</ul>'
  : '<p>Limitações finais ainda não informadas em resultados.json. Consulte o estado do projeto e a matriz; ausência de registro não equivale a ausência de risco.</p>'
